import { LESSON_EPISODES, LESSON_INDEX_OVERLAYS, LESSON_QUESTS } from './__generated__/lessons-index';
import { loadLessonStage } from './lesson-modules';
import { lessonLookup, shippedLessonStages } from '../logic/lessons/lesson-lookup';

/**
 * The shipped upper-stage lesson cells (F-CURR-001 §3.10), generated by
 * scripts/build-lessons.mjs from content/episodes/stage-<n>/*.json. The headers
 * (episodes, quests and their glosses) load at start; each stage's game scopes
 * load the first time one of its quests asks for them.
 */
export const lessonEpisodes = LESSON_EPISODES;
export const lessonQuests = LESSON_QUESTS;
export const lessonIndexOverlays = LESSON_INDEX_OVERLAYS;

export const lessons = lessonLookup(loadLessonStage, shippedLessonStages(LESSON_EPISODES));
